-- Collected data tables as CollectedDataProvider creates them on SQL Server.
-- Base table per form + one table per page named <Form><PageId>, joined on GlobalRecordId.
USE [EpiRehearsal];
GO
CREATE TABLE [dbo].[CaseReport] (
    [UniqueKey] int IDENTITY(1,1) PRIMARY KEY NOT NULL,
    [RecStatus] smallint NOT NULL DEFAULT 1,
    [GlobalRecordId] nvarchar(255) NOT NULL,
    [FirstSaveLogonName] nvarchar(255),
    [FirstSaveTime] datetime,
    [LastSaveLogonName] nvarchar(255),
    [LastSaveTime] datetime,
    [FKEY] nvarchar(255)
);
GO
CREATE TABLE [dbo].[CaseReport1] (
    [GlobalRecordId] nvarchar(255) PRIMARY KEY NOT NULL,
    [LastName] nvarchar(4000),
    [FirstName] nvarchar(4000),
    [PhoneNumber] nvarchar(20),
    [Address] nvarchar(4000),
    [City] nvarchar(4000),
    [State] nvarchar(255),
    [County] nvarchar(4000),
    [Zip] nvarchar(4000),
    [Age] float,
    [Sex] nvarchar(255),
    [Ethnicity] nvarchar(255),
    [Race] nvarchar(255),
    [ErythemaMigrans] nvarchar(255),
    [Arthritis] nvarchar(255),
    [BellsPalsy] nvarchar(255),
    [Radiculoneuropathy] nvarchar(255),
    [LymphocyticMeningitis] nvarchar(255),
    [Encephalitis] nvarchar(255),
    [CSF] nvarchar(255),
    [Antibody] nvarchar(255),
    [AtrloventricularBlock] nvarchar(255),
    [OtherClinical] nvarchar(4000),
    [OnsetDate] datetime,
    [DiagnosisDate] datetime,
    [ReportDate] datetime,
    [Hospitalized] nvarchar(255),
    [Antibiotics] nvarchar(4000),
    [AntibioticUseDays] float,
    [Pregnant] nvarchar(255),
    [ExposedCounty] nvarchar(4000),
    [ExposedState] nvarchar(255),
    [SerologicResults] nvarchar(255),
    [CultureResults] nvarchar(255),
    [OtherLabResult] nvarchar(4000),
    [PhysicianName] nvarchar(4000),
    [PhysicianPhone] nvarchar(20),
    [PhysicianAddress] nvarchar(4000),
    [PersonCompletingForm] nvarchar(4000),
    [PersonCompletingFormPhone] nvarchar(20),
    [PersonCompletingFormAddress] nvarchar(4000),
    [StateIDNumber] nvarchar(4000),
    [CDCIDNumber] nvarchar(4000),
    [ReportedToCDCDate] datetime
);
GO
CREATE TABLE [dbo].[FoodHistory] (
    [UniqueKey] int IDENTITY(1,1) PRIMARY KEY NOT NULL,
    [RecStatus] smallint NOT NULL DEFAULT 1,
    [GlobalRecordId] nvarchar(255) NOT NULL,
    [FirstSaveLogonName] nvarchar(255),
    [FirstSaveTime] datetime,
    [LastSaveLogonName] nvarchar(255),
    [LastSaveTime] datetime,
    [FKEY] nvarchar(255)
);
GO
